using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Diagnostics;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
namespace MacFlow
{
    internal static class StabilityVisual
    {
        private static void CaptureFrame(Window window,string file){Native.RECT rect;if(!Native.GetWindowRect(new System.Windows.Interop.WindowInteropHelper(window).Handle,out rect))throw new Exception("El pliegue terminó antes de capturar el cuadro");using(var bitmap=new System.Drawing.Bitmap(rect.Right-rect.Left,rect.Bottom-rect.Top))using(var graphics=System.Drawing.Graphics.FromImage(bitmap)){graphics.CopyFromScreen(rect.Left,rect.Top,0,0,bitmap.Size);bitmap.Save(file,System.Drawing.Imaging.ImageFormat.Png);}}
        private static void Check(bool value,string label,List<string> report){if(!value)throw new Exception(label);report.Add("PASS "+label);}
        internal static int Run(string folder)
        {
            folder=Path.GetFullPath(folder);Directory.CreateDirectory(folder);Log.DirectoryPath=folder;var results=new List<string>();var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Desktop desktop=null;Window background=null;ActivityIsland island=null;PrivacyScreen privacy=null;
            app.DispatcherUnhandledException+=delegate(object s,System.Windows.Threading.DispatcherUnhandledExceptionEventArgs e){results.Add("FAIL Dispatcher: "+e.Exception);File.WriteAllLines(Path.Combine(folder,"stability-tests.txt"),results);e.Handled=true;app.Shutdown(1);};
            app.Startup+=async delegate
            {
                try
                {
                    Motion.TestClientAreaAnimations=true;var directory=Path.Combine(folder,"profile");new SettingsStore(directory).Save(new Preferences{ContainedDockApplied=true,Theme="Dark",DockAutoHide=false,HideDockInApps=false,HideDockInCodex=false,HideInFullscreen=false});desktop=new Desktop(directory,true,true);
                    background=new VisualTestBackground{WindowState=WindowState.Normal,Width=SystemParameters.PrimaryScreenWidth,Height=SystemParameters.PrimaryScreenHeight,WindowStyle=WindowStyle.None,ShowActivated=false,Left=0,Top=0};background.SourceInitialized+=delegate{Native.NoActivate(background);};background.Show();
                                        var chord=new PrivacyChordState();Check(chord.Process(0x5B,true,false,true,false)==1&&chord.Process(0x5B,true,true,true,false)==0&&chord.Process(0x12,true,true,true,false)==2,"Ctrl seguido de Windows activa una sola vez; Alt recupera aunque se presione después",results);chord.Process(0x5B,false,true,true,false);Check(chord.Process(0x11,true,true,false,false)==1,"Windows seguido de Ctrl también activa Privacidad",results);chord.Process(0x11,false,true,true,true);Check(chord.Process(0x5B,true,false,true,true)==2,"recuperación simultánea no abre Privacidad",results);
                    Design.Reveal(null);Design.Dismiss(null);Design.Minimize(null);var stale=Design.Panel("Prueba de ciclo de vida",240,120);stale.ShowActivated=false;stale.Show();stale.Close();Design.Reveal(stale);Design.Dismiss(stale);Design.Minimize(stale);Check(!WindowLife.Alive(stale),"ventanas nulas y referencias cerradas no vuelven a mostrarse ni reciben transiciones",results);
                    desktop.Preferences.ShowWidget=true;desktop.Widgets.State.Items.Clear();Check(desktop.Widgets.Add("Calendar"),"se crea un widget real",results);desktop.Widgets.SetVisible(true);var widget=desktop.Widgets.Windows.Single();widget.Close();desktop.Widgets.SetVisible(true);Check(!desktop.Widgets.Windows.Any(),"cerrar un widget lo retira del registro antes del próximo cambio de Visibility",results);desktop.Widgets.Sync();desktop.Widgets.SetVisible(true);Check(desktop.Widgets.Windows.Count()==1&&desktop.Widgets.Windows.Single()!=widget,"sincronizar recrea una instancia nueva y conserva su configuración",results);
                    for(int n=0;n<4;n++){desktop.OpenSettings();var first=desktop.Settings;first.Close();desktop.OpenSettings();Check(desktop.Settings!=first&&desktop.Settings.IsVisible,"cerrar y reabrir Configuración usa una instancia nueva · "+n,results);desktop.Settings.Close();}
                    var media=new MediaFixture();media.State.CanToggle=false;media.State.Playing=false;island=new ActivityIsland(desktop,media);await Task.Delay(650);double idleTop=island.View.Top;island.Toggle();await Task.Delay(160);Check(!island.Expanded&&Math.Abs(island.View.Width-126)<1,"clic en reposo no abre controles ni inventa actividades",results);
                    media.State.CanToggle=true;media.State.Playing=true;media.State.Title="Actividad de prueba";island.Refresh();await Task.Delay(600);island.Toggle();await Task.Delay(750);Check(island.Expanded&&island.View.Top>=desktop.TopBar.Top+desktop.TopBar.Height+7&&Math.Abs(island.View.Height-204)<1,"actividad se despliega debajo de la barra con separación real",results);await Program.CaptureOwnWindow(island.View,Path.Combine(folder,"island-expanded.png"));island.Toggle();await Task.Delay(750);Check(Math.Abs(island.View.Top-idleTop)<1&&Math.Abs(island.View.Height-32)<1,"contraer recupera la posición compacta sin salto ni solapamiento",results);media.State.CanToggle=false;media.State.Playing=false;island.Refresh();island.Toggle();await Task.Delay(600);Check(!island.Expanded,"terminar la actividad vuelve al estado inerte",results);island.Dispose();island=null;
                    foreach(string theme in new[]{"Dark","Light"}){desktop.Preferences.Theme=theme;desktop.ApplyPreferences(desktop.Preferences,null);desktop.OpenControl();await Task.Delay(850);Check(((ControlCenter)desktop.Control).VolumeSlider.IsEnabled,"Centro de control conserva el backend real · "+theme,results);await Program.CaptureOwnWindow(desktop.Control,Path.Combine(folder,"control-"+theme+".png"));desktop.Control.Close();desktop.OpenWidgets(null);await Task.Delay(500);var gallery=app.Windows.OfType<WidgetGallery>().Single();await Program.CaptureOwnWindow(gallery,Path.Combine(folder,"widgets-"+theme+".png"));gallery.Close();}
                                        using(var fold=new LidTransition(desktop.Dock,()=>false)){var texture=WallpaperLibrary.Load(directory)[0].Thumbnail;Check(fold.PreviewFixture(texture),"probar pliegue funciona aunque el seguimiento automático esté desactivado",results);await Task.Delay(250);Check(fold.View!=null&&fold.View.IsVisible,"el pliegue tiene una superficie visible propia",results);CaptureFrame(fold.View,Path.Combine(folder,"desktop-fold.png"));await Task.Delay(1100);Check(fold.View==null,"el pliegue termina y libera captura, ventana y reloj",results);}
                    var wakeSignal=new TaskCompletionSource<bool>();var textSignal=new TaskCompletionSource<string>();using(var localVoice=new OfflineVoice(app.Dispatcher,directory,()=>new ProcessStartInfo(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"MacFlow.Voice.exe"),"--fixture"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true})){localVoice.Wake+=delegate{wakeSignal.TrySetResult(true);};localVoice.SetWake(true);Check(await Task.WhenAny(wakeSignal.Task,Task.Delay(6000))==wakeSignal.Task,"activación del proceso local sin capturar micrófono en la prueba",results);localVoice.Listen(text=>textSignal.TrySetResult(text),error=>textSignal.TrySetException(new Exception(error)));Check(await Task.WhenAny(textSignal.Task,Task.Delay(3000))==textSignal.Task&&await textSignal.Task=="centro de control","la misma sesión cambia de activación a dictado y entrega la orden",results);localVoice.CancelDictation();}
                    var profile=new PrivacyProfile(directory);await Task.Run(()=>profile.SetPin("738492"));Check(!File.ReadAllText(Path.Combine(directory,"privacy.dat")).Contains("738492"),"PIN y perfil se guardan con protección de la cuenta de Windows",results);profile=new PrivacyProfile(directory);Check(await Task.Run(()=>profile.Verify("738492")),"PIN correcto se verifica después de volver a leer el perfil",results);for(int n=0;n<5;n++)Check(!await Task.Run(()=>profile.Verify("000000")),"PIN incorrecto rechazado · "+n,results);Check(profile.RetryUtc>DateTime.UtcNow&&!profile.Verify("738492"),"cinco fallos aplican espera incluso al PIN correcto",results);await Task.Run(()=>profile.SetPin("738492"));
                    desktop.Activity.Add("MacFlow","Música y tareas continúan durante Privacidad");desktop.OpenPrivacy();privacy=desktop.Privacy;await Task.Delay(900);Check(privacy!=null&&privacy.IsVisible&&desktop.PresentationActive&&!privacy.CameraRunning,"privacidad cubre el escritorio sin iniciar la cámara sin una acción del usuario",results);await Program.CaptureOwnWindow(privacy,Path.Combine(folder,"privacy.png"));desktop.RecoverPrivacy();Check(desktop.Privacy==null&&!desktop.PresentationActive,"la recuperación cierra Privacidad y restaura el escritorio",results);privacy=null;
                    desktop.OpenUpdateTour();await Task.Delay(650);var tour=app.Windows.OfType<UpdateTour>().Single();for(int n=0;n<7;n++){await Task.Delay(500);Check(tour.Step==n&&tour.PreviewVisible,"demostración renovada carga y libera cada componente · "+n,results);await Program.CaptureOwnWindow(tour,Path.Combine(folder,"tour-"+n+".png"));tour.Advance();}Check(tour.Completed,"las siete demostraciones terminan sin dejar ventanas ni cámaras",results);desktop.EndPresentation();
                    var process=Process.GetCurrentProcess();await Task.Delay(1200);TimeSpan cpu=process.TotalProcessorTime;var start=DateTime.UtcNow;await Task.Delay(6000);process.Refresh();results.Add("INFO reposo 6 s: CPU equivalente a un núcleo "+(100*(process.TotalProcessorTime-cpu).TotalSeconds/(DateTime.UtcNow-start).TotalSeconds).ToString("F2")+"%; privada "+(process.PrivateMemorySize64/1048576)+" MB; máquina "+Environment.ProcessorCount+" procesadores lógicos. Cámara no activada en la suite.");
                    desktop.Dispose();desktop.Dispose();desktop.OpenSettings();desktop.OpenControl();desktop.OpenSearch();desktop.OpenFocus();desktop.OpenWidgets(null);Check(desktop.Settings==null&&desktop.Control==null&&desktop.Search==null,"salida es idempotente y los eventos tardíos no reabren paneles",results);desktop=null;File.WriteAllLines(Path.Combine(folder,"stability-tests.txt"),results);app.Shutdown();
                }
                catch(Exception ex){results.Add("FAIL "+ex);File.WriteAllLines(Path.Combine(folder,"stability-tests.txt"),results);app.Shutdown(1);}
            };
            app.Exit+=delegate{if(island!=null)island.Dispose();if(privacy!=null)privacy.Recover();if(desktop!=null)desktop.Dispose();if(background!=null)background.Close();Motion.TestClientAreaAnimations=null;};return app.Run();
        }
    }
}
